"""Utilities for spam and toxicity based chat moderation."""

import time

SPAM_MESSAGE_WINDOW_SECONDS = 10
SPAM_MESSAGE_LIMIT = 5
MUTE_DURATION_MS = 5 * 60 * 1000
TOXICITY_DECAY_PER_SECOND = 0.02
SEVERITY_THRESHOLD_PERCENT = 80
MAX_MESSAGE_BYTES = 2000

_violation_history = {}
_toxicity_scores = {}
_mutes = {}


def _prune_old_violations(user_id, now):
    history = _violation_history.get(user_id, [])
    cutoff = now - SPAM_MESSAGE_WINDOW_SECONDS
    return [t for t in history if t >= cutoff]


def _current_toxicity(user_id, now):
    entry = _toxicity_scores.get(user_id)
    if entry is None:
        return 0.0
    score, last_seen = entry
    elapsed = max(0.0, now - last_seen)
    decayed = score - TOXICITY_DECAY_PER_SECOND * elapsed
    return max(0.0, decayed)


def _apply_toxicity_hit(user_id, now, hit):
    updated = min(1.0, _current_toxicity(user_id, now) + hit)
    _toxicity_scores[user_id] = (updated, now)
    return updated


def _mute_user(user_id, now):
    expires_at = now + MUTE_DURATION_MS
    _mutes[user_id] = expires_at
    return expires_at


def _maybe_mute(user_id, now, violation_count, severity_percent):
    if violation_count > SPAM_MESSAGE_LIMIT:
        return _mute_user(user_id, now), "rate_limited"
    if severity_percent >= SEVERITY_THRESHOLD_PERCENT:
        return _mute_user(user_id, now), "toxicity"
    return None, None


def is_muted(user_id, now):
    expires_at = _mutes.get(user_id)
    return expires_at is not None and now < expires_at


def moderate_message(user_id, text, now=None):
    if now is None:
        now = time.time()

    if is_muted(user_id, now):
        return {"allowed": False, "reason": "muted"}

    if len(text.encode("utf-8")) > MAX_MESSAGE_BYTES:
        return {"allowed": False, "reason": "message_too_long"}

    history = _prune_old_violations(user_id, now)
    history.append(now)
    _violation_history[user_id] = history

    base_hit = 0.15 if len(history) > 1 else 0.05
    toxicity = _apply_toxicity_hit(user_id, now, base_hit)
    severity_percent = toxicity * 100

    expires_at, reason = _maybe_mute(
        user_id, now, len(history), severity_percent
    )
    if expires_at is not None:
        return {"allowed": False, "reason": reason, "muted_until": expires_at}

    return {"allowed": True, "reason": None, "toxicity_percent": severity_percent}
